from pathlib import Path
import json,hashlib,shutil,subprocess
root=Path.cwd();stage=root/'.local/step07-ci-history';out=root/'docs/evidence/step-07/ci-history';source=json.loads((stage/'source-freeze.json').read_text())['sourceSHA'];assert subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()==source;out.mkdir(parents=True,exist_ok=False);sha=lambda b:hashlib.sha256(b).hexdigest();origins=[]
def capture(p,target,exact=False):
 raw=p.read_bytes();q=out/target;q.parent.mkdir(parents=True,exist_ok=True)
 if exact:shutil.copyfile(p,q)
 elif p.suffix in ['.log','.py','.mjs','.yml','.ts']:
  q.write_text(json.dumps({'privateOriginal':str(p.relative_to(root)),'originalSHA256':sha(raw),'originalBytes':len(raw),'text':raw.decode().replace(str(root),'<CODING_WORKTREE>'),'sanitized':True},indent=2)+'\n')
 else:q.write_text(raw.decode().replace(str(root),'<CODING_WORKTREE>'))
 origins.append({'privateOriginal':str(p.relative_to(root)),'originalSHA256':sha(raw),'originalBytes':len(raw),'evidenceCopy':str(q.relative_to(out)),'evidenceSHA256':sha(q.read_bytes()),'evidenceBytes':q.stat().st_size,'exact':exact})
for p in sorted(stage.iterdir()):
 if not p.is_file() or p.name in ['prior-coding-progress.json','source-before.json']:continue
 if p.suffix=='.json':capture(p,'results/'+p.name)
 elif p.suffix in ['.log','.py','.yml']:capture(p,'raw/'+p.name+'.json')
for p in sorted((stage/'legacy-sources').glob('*.ts')):capture(p,'legacy-six-source/'+p.name+'.json')
p=stage/'full-history-workspace/.local/legacy-import.mjs';capture(p,'raw/legacy-import.mjs.json')
manifest=next((stage/'full-history-workspace').glob('artifacts/step07-'+source[:12]+'*/manifest.json'));capture(manifest,'engineering-manifest.json',exact=True)
# External pinned action code stays private; publish URLs/hash and the small default expression only.
upstream=json.loads((stage/'checkout-upstream.json').read_text())['files']
for row in upstream:
 p=root/row['path'];assert sha(p.read_bytes())==row['sha256'] and p.stat().st_size==row['bytes']
p=stage/'checkout-pinned-source/dist-index.js';runtime=json.loads((stage/'checkout-runtime-default.json').read_text());assert sha(p.read_bytes())==runtime['sha256']
privateFiles=[]
for p in sorted(stage.iterdir()):
 if p.is_file():privateFiles.append({'path':str(p.relative_to(root)),'sha256':sha(p.read_bytes()),'bytes':p.stat().st_size})
(out/'original-file-provenance.json').write_text(json.dumps({'sourceSHA':source,'files':origins,'externalPinnedActionFilesVerified':upstream,'externalRuntimeBundleVerified':{k:runtime[k] for k in ['url','privateRawPath','sha256','bytes']},'privateFiles':privateFiles,'privateSnapshot':'Raw logs/probes fixed snapshot, later progress/commit audit separate; no Git object stores/node_modules/pnpm cache copied'},indent=2)+'\n')
(out/'configuration.json').write_text(json.dumps({'role':'step_coder','model':'gpt-6.1-sol','reasoningEffort':'xhigh','serviceTier':'default(Standard)','sameNativeCID':'01a132c0-f44b-75f0-bea5-7f4e5e77a6ea','serverFinalFields':'UNVERIFIED_NOT_EXPOSED','clientReceiptPreserved':'docs/evidence/step-07/fix-round4/author-checkpoint/client-configuration.json','collaborationUsed':False,'globalConfigChanged':False,'formalReviewsUsed':5,'nextReview':6,'mechanicalLimit':None,'authorization':'2026-10-14 user removed mechanical five-round limit; history retained','newIndependentReview':'NOT_EXECUTED_BY_CODER','newCandidateCI':'NOT_EXECUTED_BY_CODER','ReleaseApproveMergePush':'NOT_EXECUTED','steps08_09_10':'NOT_STARTED'},indent=2)+'\n')
print('evidence captured',len(origins),'originals; actual raw SHA/bytes preserved')
